  import type { DocumentRecord, Offer, RecordSelection } from '../types'
  import Artwork from './Artwork.svelte'
  import Icon from './Icon.svelte'

  let { offer, documents, saved, onback, onrecord, onsave }: {
    offer: Offer; documents: DocumentRecord[]; saved: boolean; onback: () => void;
    onrecord: (record: RecordSelection) => void; onsave: (offer: Offer) => void;
  } = $props()
  let records = $derived(documents.filter((record) => offer.registros.includes(record.id)))
